/* 关节驱动板 DRV-JOINT B 版 示例固件。第 100 轮：经 SPI1 读编码器接口芯片 WQ-ENCIF；第 102 轮：电机控制（FOC）与 CAN；
 * 第 107 轮：输出端绝对值编码器（SSI，SPI3）——开机取绝对角度、双编码器互检、受控停车。
 * 第 110 轮：抱闸（TIM4 CH1 = PB6）——上电抱住；运动前先稳住再松闸；停、欠压先抱住再关输出；危险故障关输出同时抱闸。
 *
 * 时间基准是 20 kHz 电流环中断（motor.c）；它每 1 ms 调一次 motor_ms_hook()：
 *   第 100 轮那套编码器管理（状态、Z 相、错误计数、芯片缺失每 100 ms 重试）、状态机、指令、保护、排 CAN 发送。
 * 主循环只管把排好的 CAN 帧发出去。所有 SPI 访问都在电流环中断里，不会互相打断。
 * 板上没有调试串口：遥测区 tlm（编码器，第 100 轮）和 mc（电机控制，motor.h）给调试器经 SWD 看（仿真里由 Renode 读内存）。
 * 示例固件，仿真验证；芯片未流片、B 版不投产。 */
#include <stdint.h>
#include "brake.h"
#include "can.h"
#include "can_proto.h"
#include "clock.h"
#include "encif.h"
#include "motor.h"
#include "regs.h"
#include "ssi.h"

#define CPR 10000          /* 2500 线编码器 ×4（第 88 轮的示例编码器） */
#define WIN_MS 10          /* 转速取 10 ms 窗口 */
#define RETRY_MS 100

enum { ST_BOOT = 0, ST_RUN = 1, ST_MISSING = 2 };

typedef struct {
    uint32_t magic;        /* "TLM1" */
    uint32_t state;        /* 0 启动、1 运行、2 芯片缺失 */
    uint32_t id;           /* 读到的芯片 ID */
    uint32_t ctrl;         /* 回读的控制寄存器 */
    uint32_t tick_ms;
    int32_t cnt;           /* 芯片计数（补码，可为负） */
    int32_t turns;         /* 开机以来的圈数（向下取整） */
    int32_t angle_cnt;     /* 本圈内位置 0..CPR-1（相对开机位置） */
    int32_t rpm_x10;       /* 转速 ×10 */
    int32_t idx;           /* Z 相锁存的计数 */
    uint32_t idx_valid;
    int32_t abs_cnt;       /* 绝对位置 0..CPR-1（相对 Z 相）；未见 Z 时 -1 */
    uint32_t err_count;    /* 芯片报的错误（A/B 同跳）次数 */
    uint32_t status;       /* 最近一次状态寄存器 */
    uint32_t frames;       /* SPI 帧数 */
    uint32_t retries;      /* 芯片缺失时的重试次数 */
} telemetry_t;

volatile telemetry_t tlm;
static int32_t hist[WIN_MS];

/* CAN 收到的指令（FDCAN 中断写，1 kHz 节拍读） */
static volatile uint32_t cmd_mode, cmd_new;
static volatile int32_t cmd_target;
static uint32_t pend_mode;          /* 第 110 轮：运动指令等松闸（mc.pend） */
static int32_t pend_target;
static uint32_t last_cmd_ms, uv_ms, prev_state, mis_ms;

#define ABS_ZERO_MDEG 0      /* 输出端编码器的安装零点（编码器读 0 时关节在 0°；示例） */
#define MISMATCH_MDEG 500    /* 两个编码器差超过 0.5°（示例）…… */
#define MISMATCH_MS 10       /* ……连续 10 ms 判“减速器 / 编码器不一致” */
#define SSI_BAD_MAX 5        /* 连续 5 帧读坏判“输出端编码器”故障 */

/* 第 107 轮：读输出端绝对值编码器（1 kHz）；开机回原点；电机侧换算的关节角与它互检 */
static void abs_encoder(void)
{
    uint32_t pos;
    if (!ssi_read(&pos)) {
        if (++mc.ssi_bad >= SSI_BAD_MAX && mc.state != STATE_FAULT) {
            motor_fault(FAULT_ABS, 0);
        }
        return;
    }
    mc.ssi_bad = 0;
    int32_t a = (int32_t)((uint64_t)pos * 360000u / SSI_COUNTS) - ABS_ZERO_MDEG;
    if (a > 180000) {
        a -= 360000;
    }
    mc.abs_mdeg = a;
    if (!mc.homed && motor_aligned() && mc.state == STATE_READY) {
        motor_set_home(a);                       /* 对零做完：这时的电机计数对应输出端编码器读到的角度 */
    }
    if (mc.homed) {
        int32_t d = motor_joint_mdeg(mc.pos_cnt) - a;
        d = d > 180000 ? d - 360000 : (d < -180000 ? d + 360000 : d);
        mc.mismatch_mdeg = d;
        if ((d > MISMATCH_MDEG || d < -MISMATCH_MDEG) && (mc.state == STATE_RUN || mc.state == STATE_READY || mc.hold)) {
            if (++mis_ms >= MISMATCH_MS) {
                motor_fault(FAULT_SLIP, (float)d / 1000.0f);
            }
        } else {
            mis_ms = 0;
        }
    }
}
/* 待发的 CAN 帧（1 kHz 节拍排，主循环发） */
static volatile uint32_t due_status, due_heart, due_emcy;

static int32_t mod_cpr(int32_t x) { int32_t r = x % CPR; return r < 0 ? r + CPR : r; }
static int32_t div_cpr(int32_t x) { return (x - mod_cpr(x)) / CPR; }

/* ---------------------------------------------------------------- 编码器芯片（第 100 轮） */
static int chip_start(void)
{
    encif_reset();
    tlm.id = encif_read(ENCIF_R_ID);
    tlm.frames++;
    if (tlm.id != ENCIF_ID) {
        return 0;
    }
    encif_write(ENCIF_R_CTRL, 0x31);          /* 使能、不反向、Z 不清零、滤波长度 3 */
    tlm.ctrl = encif_read(ENCIF_R_CTRL);
    encif_write(ENCIF_R_STATUS, ENCIF_ST_ERR | ENCIF_ST_IVLD);
    tlm.frames += 3;
    for (int i = 0; i < WIN_MS; i++) {
        hist[i] = 0;
    }
    tlm.idx_valid = 0;
    tlm.abs_cnt = -1;
    return 1;
}

/* 1 ms：计数用电流环本周期读到的；再读 ID（芯片还在不在）和状态 */
static void enc_sample(uint32_t now)
{
    int32_t c = mc.pos_cnt;
    uint32_t id = encif_read(ENCIF_R_ID);
    uint32_t st = encif_read(ENCIF_R_STATUS);
    tlm.frames += 2;
    if (id != ENCIF_ID) {                     /* 芯片不响应 */
        tlm.state = ST_MISSING;
        return;
    }
    tlm.cnt = c;
    tlm.status = st;
    tlm.turns = div_cpr(c);
    tlm.angle_cnt = mod_cpr(c);

    int k = (int)(now % WIN_MS);
    if (now >= WIN_MS) {
        tlm.rpm_x10 = (c - hist[k]) * 6;      /* 计数/10 ms → rpm×10：d / CPR / 0.01 s × 60 × 10 = d × 6 */
    }
    hist[k] = c;

    if (st & ENCIF_ST_IVLD) {                 /* 过了 Z：取锁存值，清标志等下一次 */
        tlm.idx = (int32_t)encif_read(ENCIF_R_IDX);
        tlm.idx_valid = 1;
        encif_write(ENCIF_R_STATUS, ENCIF_ST_IVLD);
        tlm.frames += 2;
    }
    if (tlm.idx_valid) {
        tlm.abs_cnt = mod_cpr(c - tlm.idx);
    }
    if (st & ENCIF_ST_ERR) {                  /* A/B 同时跳：丢步风险，记一次并清除；电机在转就停机 */
        tlm.err_count++;
        encif_write(ENCIF_R_STATUS, ENCIF_ST_ERR);
        tlm.frames++;
        if (mc.state == STATE_RUN) {
            motor_fault(FAULT_ENC, 0);
        }
    }
}

/* ---------------------------------------------------------------- CAN 收 */
void can_rx_handler(uint16_t id, const uint8_t *d, uint8_t len)
{
    mc.can_rx++;
    if (id != CAN_ID_CMD || len < 5) {
        return;
    }
    cmd_target = (int32_t)((uint32_t)d[1] | (uint32_t)d[2] << 8 | (uint32_t)d[3] << 16 | (uint32_t)d[4] << 24);
    cmd_mode = d[0];
    cmd_new = 1;
}

/* ---------------------------------------------------------------- 1 kHz 节拍（在电流环中断里） */
void motor_ms_hook(uint32_t now)
{
    tlm.tick_ms = now;
    if (tlm.state == ST_RUN) {
        enc_sample(now);
    } else if (now % RETRY_MS == 0) {
        tlm.retries++;
        if (chip_start()) {
            tlm.state = ST_RUN;
        }
    }

    /* 编码器丢了：转着就停机报警；没对零就等着 */
    if (tlm.state != ST_RUN && (mc.state == STATE_RUN || mc.state == STATE_INIT) && mc.moe) {
        motor_fault(FAULT_ENC, 0);
    }
    abs_encoder();

    /* 对零：编码器正常、电流零点量好（开机 64 个周期）之后 */
    if (mc.state == STATE_INIT && !mc.moe && !motor_aligned() && tlm.state == ST_RUN && mc.isr > 64u) {
        motor_start_align();
    }

    /* 指令 */
    if (cmd_new) {
        cmd_new = 0;
        last_cmd_ms = now;
        uint32_t m = cmd_mode;
        if (m == MODE_CLEAR) {
            if (mc.state == STATE_FAULT && mc.hold) {   /* 受控停车保持中：接着运行，保持在当前位置 */
                motor_resume_hold();
            } else if (mc.state == STATE_FAULT && tlm.state == ST_RUN && mc.ssi_bad < SSI_BAD_MAX) {
                uint32_t f = mc.fault;
                mc.fault = FAULT_NONE;
                mc.fault_val = 0;
                if (f == FAULT_ENC || f == FAULT_SLIP) {   /* 编码器芯片可能复位过 / 两个编码器对不上：重新对零、回原点 */
                    mc.state = STATE_INIT;
                    mc.homed = 0;
                    motor_start_align();
                } else {
                    mc.state = STATE_READY;
                }
            }
        } else if (m == MODE_STOP) {
            if (mc.state == STATE_RUN) {               /* 第 110 轮：减速停住 → 抱闸 → 抱住后关输出（原来立即关输出） */
                mc.pend = 0;
                motor_park();
            }
        } else if ((m == MODE_SPEED || m == MODE_POS || m == MODE_TORQUE) &&
                   (mc.state == STATE_READY || mc.state == STATE_RUN)) {
            if (mc.state == STATE_READY) {             /* 第 110 轮：先在当前位置稳住、松闸，松开了再执行指令 */
                if (mc.hold) {                         /* 正在“停”的抱闸过程中：不关输出了，重新松闸 */
                    mc.hold = 0;
                    brake_set(1);
                } else {
                    motor_hold_here();
                }
                mc.state = STATE_RUN;
                mc.pend = 1;
            }
            if (mc.pend) {
                pend_mode = m;
                pend_target = cmd_target;
            } else {
                motor_set(m, cmd_target);
            }
        }
    }

    /* 第 110 轮：松开了才执行等着的运动指令 */
    if (mc.pend && mc.state != STATE_RUN) {
        mc.pend = 0;
    }
    if (mc.pend && brake_released()) {
        mc.pend = 0;
        motor_set(pend_mode, pend_target);
    }

    /* 保护：通信超时、欠压（连续 5 ms）——第 107 轮起受控停车：通信超时减速停住、保持位置不断电；欠压减速停住后关输出 */
    if (mc.state == STATE_RUN && now - last_cmd_ms > 100u) {
        motor_quickstop(FAULT_COMM, 0, 1);
    }
    if ((mc.state == STATE_READY || mc.state == STATE_RUN || mc.hold) && mc.vbus < VBUS_MIN) {
        if (++uv_ms >= 5u) {
            if (mc.hold && mc.hold_keep) {            /* 保持中又欠压：保持不住，停住后关输出；故障改记欠压，再报一次警 */
                mc.hold_keep = 0;
                mc.fault = FAULT_UV;
                mc.fault_val = mc.vbus;
                due_emcy = 1;
            } else if (mc.hold) {
                /* 已经在“停住后关输出”的受控停车里：不用再做什么 */
            } else {
                motor_quickstop(FAULT_UV, mc.vbus, 0);
            }
        }
    } else {
        uv_ms = 0;
    }

    /* 排 CAN 发送 */
    if (mc.state == STATE_FAULT && prev_state != STATE_FAULT) {
        due_emcy = 1;
    }
    prev_state = mc.state;
    if (now % 10u == 0) {
        due_status = 1;
    }
    if (now % 100u == 0) {
        due_heart = 1;
    }
}

static void put16(uint8_t *p, int32_t v)
{
    if (v > 32767) {
        v = 32767;
    }
    if (v < -32768) {
        v = -32768;
    }
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)((uint32_t)v >> 8);
}

static int32_t rnd(float x) { return (int32_t)(x >= 0 ? x + 0.5f : x - 0.5f); }

int main(void)
{
    clock_init();
    tlm.magic = 0x314D4C54u;
    tlm.state = ST_BOOT;
    tlm.abs_cnt = -1;

    encif_init_bus();
    tlm.state = chip_start() ? ST_RUN : ST_MISSING;
    ssi_init();
    brake_init();
    motor_init();
    can_init();

    for (;;) {
        __asm volatile("wfi");
        uint8_t d[8];
        if (due_emcy) {
            due_emcy = 0;
            d[0] = (uint8_t)mc.fault;
            put16(d + 1, rnd(mc.fault_val * 100.0f));
            can_send(CAN_ID_EMCY, d, 3);
            mc.can_tx++;
        }
        if (due_status) {
            due_status = 0;
            /* 关节角：回原点后按输出端绝对值编码器的原点换算电机计数（第 107 轮；原来开机位置当 0°） */
            float joint = (float)motor_joint_mdeg(mc.pos_cnt) / 1000.0f;
            d[0] = (uint8_t)mc.state;
            d[1] = (uint8_t)mc.fault;
            put16(d + 2, rnd(joint * 100.0f));
            put16(d + 4, rnd(mc.speed_rpm));
            put16(d + 6, rnd(mc.iq * 100.0f));
            can_send(CAN_ID_STATUS, d, 8);
            mc.can_tx++;
        }
        if (due_heart) {
            due_heart = 0;
            d[0] = (uint8_t)mc.state;
            put16(d + 1, rnd(mc.vbus * 10.0f));
            d[3] = (uint8_t)mc.brake_cmd;               /* 第 110 轮：抱闸 0 抱住、1 松开 */
            can_send(CAN_ID_HEART, d, 4);
            mc.can_tx++;
        }
    }
}

/* 电机控制（第 102 轮；第 107 轮加原点、受控停车；第 110 轮加抱闸时序）。一次 ADC 注入组转换完成中断 = 一个 20 kHz 电流环周期：
 *   读三相电流与母线 → 过流保护 → 读编码器（SPI1 → WQ-ENCIF）→ 电角度 → Clarke / Park → d、q 两个 PI → 反 Park → SVPWM → 写比较值
 *   每 10 次（2 kHz）速度环，每 20 次（1 kHz）位置环与轨迹、编码器状态、主程序节拍。
 * PWM：TIM1 中心对齐 20 kHz，CH1–3 PA8–PA10、CH1N–3N PB13–PB15（AF6，第 88 轮原理图第 27–32 脚）；死区 200 ns。
 * 电流：PA0–PA2 = ADC1_IN1–IN3，40 mV/A、零点 1.65 V（开机时实测零点）；母线 PA3 = ADC1_IN4，分压 6.8 / 108.8。 */
#include "motor.h"
#include "brake.h"
#include "can_proto.h"
#include "encif.h"
#include "regs.h"

volatile mc_t mc;

#define TS (1.0f / PWM_HZ)
#define PI_F 3.14159265f
#define TWO_PI 6.28318531f
#define A_PER_CODE (3.3f / 4095.0f / 0.04f)
#define V_PER_CODE (3.3f / 4095.0f * 108.8f / 6.8f)

/* 电流环：带宽 1 kHz（ωc = 2π·1000），Kp = L·ωc，Ki = R·ωc（零极点对消） */
#define KP_I (L_PHASE * TWO_PI * 1000.0f)
#define KI_I (R_PHASE * TWO_PI * 1000.0f)
/* 速度环：带宽 100 Hz，Kp = J·ωs / Kt，Ki = Kp·ωs / 4 */
#define WS (TWO_PI * 100.0f)
#define KP_W (J_TOTAL * WS / KT)
#define KI_W (KP_W * WS / 4.0f)
#define IQ_MAX 20.0f
/* 位置环：Kp = ωs / 4（rad/s 每 rad）；轨迹：电机 1500 rpm、加速度 3000 rad/s² */
#define KP_P (WS / 4.0f)
#define V_MAX (1500.0f / 60.0f * TWO_PI)
#define A_MAX 3000.0f

static float off_a = 2047.5f, off_b = 2047.5f, off_c = 2047.5f;
static uint32_t cal_n;
static float cal_a, cal_b, cal_c;
static float int_d, int_q, int_w;
static int32_t ring[20];            /* 最近 20 个周期（1 ms）的计数 */
static uint32_t ms;
static uint32_t align_t;
static int aligned;
static int32_t align_pending;      /* 对零记下的偏移，抱住以后才生效（第 110 轮） */
/* 轨迹（电机侧，单位：计数，浮点） */
static float trj_pos, trj_vel, trj_goal;

/* ---------------------------------------------------------------- 数学（不用数学库：多项式，误差 < 1e-6） */
static float wrap_pi(float x)
{
    while (x > PI_F) {
        x -= TWO_PI;
    }
    while (x < -PI_F) {
        x += TWO_PI;
    }
    return x;
}

static void sincos(float x, float *s, float *c)
{
    x = wrap_pi(x);
    float sg = 1.0f;
    if (x > PI_F / 2) {                 /* 折到 [-π/2, π/2] */
        x = PI_F - x;
        sg = -1.0f;
    } else if (x < -PI_F / 2) {
        x = -PI_F - x;
        sg = -1.0f;
    }
    float x2 = x * x;
    *s = x * (1.0f - x2 / 6.0f * (1.0f - x2 / 20.0f * (1.0f - x2 / 42.0f * (1.0f - x2 / 72.0f))));
    *c = sg * (1.0f - x2 / 2.0f * (1.0f - x2 / 12.0f * (1.0f - x2 / 30.0f * (1.0f - x2 / 56.0f * (1.0f - x2 / 90.0f)))));
}

static float clampf(float x, float lo, float hi) { return x < lo ? lo : (x > hi ? hi : x); }
static float absf(float x) { return x < 0 ? -x : x; }
static float sqrtf_(float x)
{
    if (x <= 0) {
        return 0;
    }
    float r = x > 1.0f ? x : 1.0f;
    for (int i = 0; i < 12; i++) {
        r = 0.5f * (r + x / r);
    }
    return r;
}

/* ---------------------------------------------------------------- 外设 */
void motor_init(void)
{
    mc.magic = 0x3230434Du;
    RCC_APB2ENR |= RCC_TIM1EN;
    RCC_AHB2ENR |= RCC_ADC12EN | RCC_GPIOAEN | RCC_GPIOBEN;

    /* PA8–PA10、PB13–PB15 复用 AF6；PA0–PA3 模拟 */
    GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(0x3Fu << 16)) | (0x2Au << 16);
    REG(GPIOA_BASE + 0x24) = (REG(GPIOA_BASE + 0x24) & ~0xFFFu) | 0x666u;          /* GPIOA_AFRH */
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(0x3Fu << 26)) | (0x2Au << 26);
    REG(GPIOB_BASE + 0x24) = (REG(GPIOB_BASE + 0x24) & ~(0xFFFu << 20)) | (0x666u << 20);
    GPIO_MODER(GPIOA_BASE) |= 0xFFu;

    /* TIM1：中心对齐 1、ARR 预装载；PWM 模式 1 + 比较值预装载；互补输出；死区 200 ns（34 × 5.88 ns）；更新事件作 TRGO；RCR = 1 */
    TIM1_PSC = 0;
    TIM1_ARR = PWM_ARR;
    TIM1_RCR = 1;
    TIM1_CCMR1 = (6u << 4) | (1u << 3) | (6u << 12) | (1u << 11);
    TIM1_CCMR2 = (6u << 4) | (1u << 3);
    TIM1_CCER = (1u << 0) | (1u << 2) | (1u << 4) | (1u << 6) | (1u << 8) | (1u << 10);
    TIM1_CCR1 = TIM1_CCR2 = TIM1_CCR3 = PWM_ARR / 2;
    TIM1_BDTR = 34u;                                   /* MOE 先关 */
    TIM1_CR2 = 2u << 4;
    TIM1_EGR = 1u;

    /* ADC1：时钟 HCLK/4、退出深度掉电、开稳压器、校准、使能；注入组 4 路由 TIM1_TRGO 上升沿触发 */
    ADC12_CCR = (ADC12_CCR & ~(3u << 16)) | (3u << 16);
    ADC1_CR &= ~(1u << 29);
    ADC1_CR |= 1u << 28;
    for (volatile int i = 0; i < 4000; i++) {          /* 稳压器启动 ≥ 20 µs */
    }
    ADC1_CR |= 1u << 31;
    while (ADC1_CR & (1u << 31)) {
    }
    ADC1_CR |= 1u;
    while (!(ADC1_ISR & ADC_ISR_ADRDY)) {
    }
    ADC1_JSQR = 3u | (0u << 2) | (1u << 7) | (1u << 9) | (2u << 15) | (3u << 21) | (4u << 27);
    ADC1_IER = 1u << 6;                                /* JEOSIE */
    ADC1_CR |= 1u << 3;                                /* JADSTART：等触发 */

    NVIC_IPR8(IRQ_ADC1_2) = 0x00;
    NVIC_ISER(IRQ_ADC1_2 / 32) = 1u << (IRQ_ADC1_2 % 32);
    TIM1_CR1 = (1u << 5) | (1u << 7) | 1u;             /* CMS = 01、ARPE、CEN */
}

void motor_enable(int on)
{
    if (on) {
        int_d = int_q = int_w = 0;
        TIM1_BDTR |= TIM_BDTR_MOE;
    } else {
        TIM1_BDTR &= ~TIM_BDTR_MOE;
    }
    mc.moe = on ? 1u : 0u;
}

void motor_fault(uint32_t code, float val)
{
    motor_enable(0);
    brake_set(0);                                    /* 第 110 轮：立即关输出的同时抱闸（抱住要几十毫秒） */
    if (mc.state != STATE_FAULT || mc.hold) {        /* 受控停车中又来危险故障：改记这一个，立即关输出 */
        mc.fault = code;
        mc.fault_val = val;
    }
    mc.hold = 0;
    mc.state = STATE_FAULT;
    mc.mode = MODE_STOP;
    mc.id_ref = mc.iq_ref = 0;
}

int motor_aligned(void) { return aligned; }

/* ---------------------------------------------------------------- 第 107 轮：原点、受控停车 */
void motor_set_home(int32_t abs_mdeg)
{
    mc.home_cnt = mc.pos_cnt;
    mc.home_mdeg = abs_mdeg;
    mc.homed = 1;
}

int32_t motor_joint_mdeg(int32_t cnt)
{
    return mc.home_mdeg + (int32_t)((float)(cnt - mc.home_cnt) * (360000.0f / ((float)CNT_PER_REV * GEAR)));
}

void motor_quickstop(uint32_t code, float val, int keep)
{
    if (mc.state == STATE_FAULT) {
        return;
    }
    mc.fault = code;
    mc.fault_val = val;
    mc.state = STATE_FAULT;
    if (!mc.moe) {                                   /* 输出本来就关着：没什么可停的 */
        mc.hold = 0;
        mc.mode = MODE_STOP;
        return;
    }
    const float amax = A_MAX / TWO_PI * CNT_PER_REV;
    trj_pos = (float)mc.pos_cnt;
    trj_vel = mc.speed_rpm / 60.0f * CNT_PER_REV;
    trj_goal = trj_pos + (trj_vel >= 0 ? 1.0f : -1.0f) * trj_vel * trj_vel / (2.0f * amax);   /* 按最大减速度停下的位置 */
    mc.mode = MODE_POS;
    mc.hold = 1;
    mc.hold_keep = keep ? 1u : 0u;
}

void motor_resume_hold(void)
{
    brake_set(1);                                    /* 第 110 轮：若已在抱闸（关输出类停车），重新松开 */
    mc.hold = 0;
    mc.fault = FAULT_NONE;
    mc.fault_val = 0;
    mc.state = STATE_RUN;
    mc.mode = MODE_POS;
    trj_goal = trj_pos;
}

void motor_start_align(void)
{
    aligned = 0;
    align_t = 0;
    mc.state = STATE_INIT;
    mc.mode = MODE_STOP;
    motor_enable(1);
    brake_set(1);                                    /* 第 110 轮：对零要转子能动；d 轴电流把转子定住 */
}

/* ---------------------------------------------------------------- 第 110 轮：抱闸时序 */
void motor_hold_here(void)
{
    trj_pos = trj_goal = (float)mc.pos_cnt;
    trj_vel = 0;
    mc.speed_ref = 0;
    mc.iq_ref = 0;
    mc.mode = MODE_POS;
    motor_enable(1);                                 /* 先有力矩（位置环停在这里）…… */
    brake_set(1);                                    /* ……再松闸 */
}

void motor_park(void)
{
    mc.state = STATE_READY;
    if (!mc.moe) {
        brake_set(0);
        mc.hold = 0;
        mc.mode = MODE_STOP;
        return;
    }
    const float amax = A_MAX / TWO_PI * CNT_PER_REV;
    trj_pos = (float)mc.pos_cnt;
    trj_vel = mc.speed_rpm / 60.0f * CNT_PER_REV;
    trj_goal = trj_pos + (trj_vel >= 0 ? 1.0f : -1.0f) * trj_vel * trj_vel / (2.0f * amax);
    if (mc.mode != MODE_SPEED && mc.mode != MODE_POS) {
        int_w = mc.iq_ref;                           /* 从力矩模式切过来：速度环积分接上当前电流，不跳 */
    }
    mc.mode = MODE_POS;
    mc.hold = 1;                                     /* 借用受控停车的“停住后关输出”：停住 → 抱闸 → 抱住后关输出 */
    mc.hold_keep = 0;
}

void motor_set(uint32_t mode, int32_t target)
{
    if (mode == MODE_SPEED) {
        mc.speed_ref = (float)target;
    } else if (mode == MODE_POS) {
        /* 关节角 0.001° → 电机计数：按原点换算，× 减速比 × 每转计数 / 360000（第 107 轮起按输出端编码器的原点） */
        trj_goal = (float)mc.home_cnt + (float)(target - mc.home_mdeg) * (float)GEAR * (float)CNT_PER_REV / 360000.0f;
        if (mc.mode != MODE_POS) {
            trj_pos = (float)mc.pos_cnt;
            trj_vel = mc.speed_rpm / 60.0f * CNT_PER_REV;
        }
    } else if (mode == MODE_TORQUE) {
        mc.iq_ref = (float)target / 1000.0f;
    }
    if (mc.mode != mode && (mode == MODE_SPEED || mode == MODE_POS)) {
        int_w = 0;                                     /* 切模式时速度环积分清零 */
    }
    mc.mode = mode;
}

/* ---------------------------------------------------------------- 轨迹（梯形速度，1 kHz，单位：计数） */
static void trajectory(void)
{
    const float dt = 0.001f;
    const float vmax = V_MAX / TWO_PI * CNT_PER_REV, amax = A_MAX / TWO_PI * CNT_PER_REV;
    float e = trj_goal - trj_pos;
    if (trj_vel == 0.0f && absf(e) < 0.5f) {           /* 停着、已到目标：不动（第 110 轮：原来会在 ±几个计数间来回） */
        trj_pos = trj_goal;
        mc.pos_ref_cnt = (int32_t)trj_pos;
        return;
    }
    float dir = e >= 0 ? 1.0f : -1.0f;
    float stop = trj_vel * trj_vel / (2.0f * amax);    /* 现在开始减速要走的距离 */
    float v;
    if (absf(e) <= stop + absf(trj_vel) * dt && trj_vel * dir > 0) {
        v = trj_vel - dir * amax * dt;                 /* 减速 */
        if (v * dir < 0) {
            v = 0;
        }
    } else {
        v = clampf(trj_vel + dir * amax * dt, -vmax, vmax);
    }
    trj_pos += 0.5f * (trj_vel + v) * dt;
    trj_vel = v;
    if (absf(trj_goal - trj_pos) < 0.5f && absf(trj_vel) < amax * dt) {
        trj_pos = trj_goal;
        trj_vel = 0;
    }
    mc.pos_ref_cnt = (int32_t)trj_pos;
}

/* ---------------------------------------------------------------- 20 kHz 电流环 */
void ADC1_2_IRQHandler(void)
{
    ADC1_ISR = (1u << 5) | (1u << 6);                  /* 清 JEOC、JEOS */
    float ca = (float)ADC1_JDR(0), cb = (float)ADC1_JDR(1), cc = (float)ADC1_JDR(2);
    mc.vbus = (float)ADC1_JDR(3) * V_PER_CODE;
    mc.isr++;

    /* 开机前 64 个周期：输出关着，量电流零点 */
    if (cal_n < 64) {
        cal_a += ca; cal_b += cb; cal_c += cc;
        if (++cal_n == 64) {
            off_a = cal_a / 64; off_b = cal_b / 64; off_c = cal_c / 64;
        }
    }
    float ia = (ca - off_a) * A_PER_CODE, ib = (cb - off_b) * A_PER_CODE, ic = (cc - off_c) * A_PER_CODE;
    float am = absf(ia) > absf(ib) ? absf(ia) : absf(ib);
    am = am > absf(ic) ? am : absf(ic);
    if (am > mc.imax) {
        mc.imax = am;
    }
    if (am > I_TRIP && mc.moe) {                       /* 过流：本周期就关管 */
        motor_fault(FAULT_OC, am);
    }

    /* 编码器：读计数（第 100 轮的芯片状态在 1 kHz 节拍里处理） */
    int32_t cnt = (int32_t)encif_read(ENCIF_R_CNT);
    mc.pos_cnt = cnt;
    /* 转速：与 1 ms 前的计数差分（1500 rpm 时 250 计数/ms，分辨率 6 rpm），再一阶滤波（时间常数约 1 ms：
     * 停着时编码器只在 ±1 计数间跳，滤得太轻速度环会把量化当真，电流来回抖） */
    uint32_t ri = mc.isr % 20u;
    if (mc.isr > 20u) {
        float rpm = (float)(cnt - ring[ri]) * (60000.0f / CNT_PER_REV);
        mc.speed_rpm += 0.05f * (rpm - mc.speed_rpm);
    }
    ring[ri] = cnt;
    int32_t e = (cnt - mc.align_off) % CNT_PER_EREV;
    if (e < 0) {
        e += CNT_PER_EREV;
    }
    float th = (float)e * (TWO_PI / CNT_PER_EREV);
    if (!aligned && mc.state == STATE_INIT && mc.moe) {
        th = 0;                                        /* 对零：电流加在 d 轴 θe = 0 方向，转子被拉过去 */
    }
    float s, c;
    sincos(th, &s, &c);

    /* Clarke（幅值不变）、Park */
    float al = ia, be = (ia + 2.0f * ib) * 0.57735027f;
    mc.id = al * c + be * s;
    mc.iq = -al * s + be * c;

    /* 指令 */
    uint32_t k = mc.isr % 20u;
    if (mc.state == STATE_INIT && mc.moe) {
        mc.id_ref = ALIGN_A;
        mc.iq_ref = 0;
    } else if (mc.state == STATE_RUN || mc.hold) {
        if (k % 10u == 0 && (mc.mode == MODE_SPEED || mc.mode == MODE_POS)) {
            /* 2 kHz 速度环 */
            float w = mc.speed_rpm / 60.0f * TWO_PI, wr = mc.speed_ref / 60.0f * TWO_PI;
            float ew = wr - w;
            float out = KP_W * ew + int_w;
            if (absf(out) < IQ_MAX) {
                int_w += KI_W * ew * 0.0005f;
            }
            mc.iq_ref = clampf(out, -IQ_MAX, IQ_MAX);
        }
        mc.id_ref = 0;
    } else {
        mc.id_ref = mc.iq_ref = 0;
    }

    /* d/q 电流 PI，电压限幅 Vbus/√3（SVPWM 线性区），抗积分饱和 */
    float vmax = mc.vbus * 0.57735027f;
    float ed = mc.id_ref - mc.id, eq = mc.iq_ref - mc.iq;
    float vd = KP_I * ed + int_d, vq = KP_I * eq + int_q;
    float mag = sqrtf_(vd * vd + vq * vq);
    if (mag < vmax) {
        int_d += KI_I * ed * TS;
        int_q += KI_I * eq * TS;
    } else if (mag > 0) {
        vd *= vmax / mag;
        vq *= vmax / mag;
    }
    mc.vd = vd;
    mc.vq = vq;

    /* 反 Park、反 Clarke、SVPWM（中点注入：三相减去 (max + min) / 2） */
    float va = vd * c - vq * s, vbt = vd * s + vq * c;
    float pa = va, pb = -0.5f * va + 0.8660254f * vbt, pc = -0.5f * va - 0.8660254f * vbt;
    float mx = pa > pb ? pa : pb, mn = pa < pb ? pa : pb;
    mx = mx > pc ? mx : pc;
    mn = mn < pc ? mn : pc;
    float z = -(mx + mn) * 0.5f, inv = mc.vbus > 1.0f ? 1.0f / mc.vbus : 0;
    TIM1_CCR1 = (uint32_t)(PWM_ARR * clampf(0.5f + (pa + z) * inv, 0, 1));
    TIM1_CCR2 = (uint32_t)(PWM_ARR * clampf(0.5f + (pb + z) * inv, 0, 1));
    TIM1_CCR3 = (uint32_t)(PWM_ARR * clampf(0.5f + (pc + z) * inv, 0, 1));

    /* 1 kHz：对零、位置环与轨迹、主程序节拍 */
    if (k == 0) {
        ms++;

        brake_tick(mc.vbus);
        mc.brake_cmd = (uint32_t)brake_cmd();
        mc.brake_ok = (uint32_t)(mc.brake_cmd ? brake_released() : brake_engaged());
        if (mc.state == STATE_INIT && mc.moe && ++align_t == 300) {      /* 通电 300 ms 后记偏移；第 110 轮：先抱闸 */
            int32_t o = cnt % CNT_PER_EREV;
            align_pending = o < 0 ? o + CNT_PER_EREV : o;
            brake_set(0);
        }
        if (mc.state == STATE_INIT && mc.moe && align_t == 300u + BRK_ENGAGE_MS) {   /* 抱住了才撤对零电流、关输出 */
            mc.align_off = align_pending;
            aligned = 1;
            motor_enable(0);
            mc.state = STATE_READY;
        }
        if ((mc.state == STATE_RUN || mc.hold) && mc.mode == MODE_POS) {
            trajectory();
            if (mc.hold && !mc.hold_keep && trj_vel == 0.0f && trj_pos == trj_goal) {   /* 受控停车（关输出类）：停住了再关 */
                brake_set(0);                                                         /* 第 110 轮：先抱闸，抱住了再关 */
                if (brake_engaged()) {
                    mc.hold = 0;
                    motor_enable(0);
                    mc.mode = MODE_STOP;
                }
            }
            float ep = (trj_pos - (float)cnt) * (TWO_PI / CNT_PER_REV);           /* rad */
            float wff = trj_vel / CNT_PER_REV * 60.0f;                            /* 前馈 rpm */
            mc.speed_ref = wff + KP_P * ep / TWO_PI * 60.0f;
        }
        motor_ms_hook(ms);
        mc.imax = 0;
    }
}

/* FDCAN1 驱动（经典 CAN 1 Mbit/s）。引脚 PA11 RX、PA12 TX（AF9，第 88 轮原理图第 33、34 脚）。
 * 消息 RAM 按 STM32G4 固定布局：Rx FIFO0 从 0xB0 起、Tx FIFO 从 0x278 起，每个元素 18 字（头 2 字 + 64 字节数据）。 */
#include "can.h"
#include "regs.h"

#define RAM(off) REG(SRAMCAN_BASE + (off))

void can_init(void)
{
    RCC_APB1ENR1 |= RCC_FDCANEN;
    RCC_CCIPR = (RCC_CCIPR & ~(3u << 24)) | (2u << 24);       /* FDCAN 时钟 = PCLK1 = 170 MHz */
    GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(0xFu << 22)) | (2u << 22) | (2u << 24);
    REG(GPIOA_BASE + 0x24) = (REG(GPIOA_BASE + 0x24) & ~(0xFFu << 12)) | (9u << 12) | (9u << 16);   /* GPIOA_AFRH：PA11、PA12 = AF9 */

    FDCAN1_CCCR |= 1u;                                         /* INIT */
    while (!(FDCAN1_CCCR & 1u)) {
    }
    FDCAN1_CCCR |= 2u;                                         /* CCE：允许改配置 */
    /* 1 Mbit/s：170 MHz / 10 = 17 MHz 时间份额；1 + 13 + 3 = 17 份额/位，采样点 82 % */
    FDCAN1_NBTP = (1u << 25) | (9u << 16) | (12u << 8) | 2u;
    FDCAN1_RXGFC = 0;                                          /* 不匹配的标准帧收进 FIFO0 */
    for (uint32_t i = 0; i < 0x350u; i += 4) {
        RAM(i) = 0;
    }
    FDCAN1_IE = 1u;                                            /* RF0NE */
    FDCAN1_ILE = 1u;                                           /* EINT0 */
    FDCAN1_CCCR &= ~1u;                                        /* 退出初始化，上总线 */
    NVIC_IPR8(IRQ_FDCAN1_IT0) = 0x40;                          /* 比电流环（0x00）低 */
    NVIC_ISER(IRQ_FDCAN1_IT0 / 32) = 1u << (IRQ_FDCAN1_IT0 % 32);
}

void can_send(uint16_t id, const uint8_t *data, uint8_t len)
{
    uint32_t q = FDCAN1_TXFQS;
    if (q & (1u << 21)) {                                      /* TFQF：发送队列满，丢 */
        return;
    }
    uint32_t idx = (q >> 16) & 3u;
    uint32_t a = SRAMCAN_TFQSA + idx * SRAMCAN_ESIZE;
    uint32_t w[2] = {0, 0};
    for (uint8_t i = 0; i < len && i < 8; i++) {
        w[i / 4] |= (uint32_t)data[i] << (8 * (i % 4));
    }
    RAM(a) = (uint32_t)(id & 0x7FF) << 18;                     /* T0：标准 ID 在位 28:18 */
    RAM(a + 4) = (uint32_t)len << 16;                          /* T1：DLC 在位 19:16 */
    RAM(a + 8) = w[0];
    RAM(a + 12) = w[1];
    FDCAN1_TXBAR = 1u << idx;
}

void FDCAN1_IT0_IRQHandler(void)
{
    while (FDCAN1_RXF0S & 0xFu) {
        uint32_t gi = (FDCAN1_RXF0S >> 8) & 3u;
        uint32_t a = SRAMCAN_RF0SA + gi * SRAMCAN_ESIZE;
        uint32_t r0 = RAM(a), r1 = RAM(a + 4);
        uint8_t d[8];
        uint32_t w0 = RAM(a + 8), w1 = RAM(a + 12);
        for (int i = 0; i < 4; i++) {
            d[i] = (uint8_t)(w0 >> (8 * i));
            d[i + 4] = (uint8_t)(w1 >> (8 * i));
        }
        uint8_t len = (uint8_t)((r1 >> 16) & 0xF);
        FDCAN1_RXF0A = gi;
        can_rx_handler((uint16_t)((r0 >> 18) & 0x7FF), d, len > 8 ? 8 : len);
    }
    FDCAN1_IR = 1u;                                            /* 清 RF0N */
}

#ifndef CAN_H
#define CAN_H
#include <stdint.h>

void can_init(void);
void can_send(uint16_t id, const uint8_t *data, uint8_t len);
void can_rx_handler(uint16_t id, const uint8_t *data, uint8_t len);   /* main.c 里实现 */

#endif

/* 系统时钟：HSI16 → PLL → 170 MHz（第 102 轮）。HSI16 / M=4 = 4 MHz，× N=85 = 340 MHz，/ R=2 = 170 MHz。
 * 170 MHz 要求：主调节器提升模式（PWR_CR5.R1MODE = 0）、Flash 4 个等待周期（RM0440 Flash 章“等待周期与电压”表）。 */
#include "clock.h"
#include "regs.h"

void clock_init(void)
{
    RCC_APB1ENR1 |= RCC_PWREN;
    PWR_CR5 &= ~(1u << 8);                            /* R1MODE = 0：提升模式 */
    FLASH_ACR = (FLASH_ACR & ~0xFu) | 4u | (1u << 8) | (1u << 9) | (1u << 10);   /* 4 等待周期、预取、指令 / 数据缓存 */
    RCC_PLLCFGR = 2u | (3u << 4) | (85u << 8) | (1u << 24);                    /* PLLSRC = HSI16、M = 4、N = 85、R = 2、PLLREN */
    RCC_CR |= 1u << 24;                               /* PLLON */
    while (!(RCC_CR & (1u << 25))) {                  /* 等 PLLRDY */
    }
    RCC_CFGR = (RCC_CFGR & ~3u) | 3u;                 /* SW = PLL */
    while (((RCC_CFGR >> 2) & 3u) != 3u) {            /* 等 SWS = PLL */
    }
}

/* 输出端绝对值编码器（SSI）驱动，第 107 轮。板上 J4 经两片 RS-485 收发（MAX3485，第 88 轮）：PB3 = SPI3_SCK 出时钟、PB4 = SPI3_MISO 收数据（AF6，第 98 轮）。
 * 帧（示例格式）：24 个时钟，第 1 位起始位恒 1，接着 17 位单圈位置（二进制、高位先出），再 1 位错误位（0 正常），其余补 0。
 * SPI3 主机、模式 3（时钟空闲为高、第二个边沿采样）、170 MHz / 128 ≈ 1.33 MHz；两帧之间时钟停的时间远大于编码器的单稳态时间（约 15 µs）。 */
#include "ssi.h"
#include "regs.h"

void ssi_init(void)
{
    RCC_APB1ENR1 |= RCC_SPI3EN;
    RCC_AHB2ENR |= RCC_GPIOBEN;
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(0xFu << 6)) | (2u << 6) | (2u << 8);       /* PB3、PB4 复用 */
    GPIO_AFRL(GPIOB_BASE) = (GPIO_AFRL(GPIOB_BASE) & ~(0xFFu << 12)) | (6u << 12) | (6u << 16);      /* AF6 = SPI3 */
    SPI3_CR1 = SPI_CR1_MSTR | SPI_CR1_BR_DIV128 | SPI_CR1_SSM | SPI_CR1_SSI | SPI_CR1_CPOL | SPI_CR1_CPHA;
    SPI3_CR2 = SPI_CR2_DS_8BIT | SPI_CR2_FRXTH;
    SPI3_CR1 |= SPI_CR1_SPE;
}

static uint8_t xfer(void)
{
    while (!(SPI3_SR & SPI_SR_TXE)) {
    }
    SPI3_DR8 = 0xFF;
    while (!(SPI3_SR & SPI_SR_RXNE)) {
    }
    return SPI3_DR8;
}

int ssi_read(uint32_t *pos)
{
    uint32_t f = 0;
    for (int i = 0; i < 3; i++) {
        f = (f << 8) | xfer();
    }
    while (SPI3_SR & SPI_SR_BSY) {
    }
    if (f == 0xFFFFFFu || !(f & (1u << 23)) || (f & (1u << 5))) {   /* 线断（全 1）、没有起始位、错误位 */
        return 0;
    }
    *pos = (f >> 6) & (SSI_COUNTS - 1u);
    return 1;
}

/* 输出端绝对值编码器（SSI，第 107 轮）。帧格式见 ssi.c。 */
#ifndef SSI_H
#define SSI_H
#include <stdint.h>

#define SSI_BITS 17
#define SSI_COUNTS (1u << SSI_BITS)   /* 131 072 计数/圈 */

void ssi_init(void);
/* 读一帧：返回 1 = 帧有效（起始位为 1、错误位为 0、不是全 1），*pos 为 0..SSI_COUNTS-1 */
int ssi_read(uint32_t *pos);

#endif

/* 抱闸（第 110 轮）。电路（B 版原理图第 1 页）：PB6 → U16 UCC27511 → Q7 低边 MOSFET，线圈接 J6（母线 + / Q7 漏极），D5 续流；
 * R38 100 kΩ 下拉：MCU 复位、程序跑飞、没配置时 PB6 没输出 → 线圈断电 → 抱住（失效安全）。
 * PWM：TIM4 向上计数 170 MHz / 8500 = 20 kHz；松闸先 100% 过励 BRK_OVER_MS，再保持占空比 = 24 V ÷ 母线电压（平均 24 V）。
 * 线圈电感大（时间常数几十毫秒，示例 25 ms），20 kHz 下电流基本是直流。示例固件，仿真验证。 */
#include "brake.h"
#include "regs.h"

#define BRK_ARR 8499u          /* 170 MHz / (8499 + 1) = 20 kHz */

static uint32_t cmd_release, ms_since;

void brake_init(void)
{
    RCC_APB1ENR1 |= RCC_TIM4EN;
    RCC_AHB2ENR |= RCC_GPIOBEN;
    TIM4_PSC = 0;
    TIM4_ARR = BRK_ARR;
    TIM4_CCR1 = 0;                                         /* 占空比 0：抱住 */
    TIM4_CCMR1 = (6u << 4) | (1u << 3);                    /* OC1M = 0110 PWM 模式 1，OC1PE 预装载 */
    TIM4_CCER = 1u;                                        /* CC1E */
    TIM4_EGR = 1u;                                         /* UG：装入预装载值 */
    TIM4_CR1 = (1u << 7) | 1u;                             /* ARPE、CEN */
    /* PB6 复用 AF2 = TIM4_CH1（引脚复用对照 ST 引脚数据） */
    GPIO_AFRL(GPIOB_BASE) = (GPIO_AFRL(GPIOB_BASE) & ~(0xFu << 24)) | (2u << 24);
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(3u << 12)) | (2u << 12);
    cmd_release = 0;
    ms_since = BRK_ENGAGE_MS;                              /* 上电就是抱着的 */
}

void brake_set(int release)
{
    uint32_t r = release ? 1u : 0u;
    if (r == cmd_release) {
        return;
    }
    cmd_release = r;
    ms_since = 0;
    TIM4_CCR1 = r ? BRK_ARR + 1u : 0u;                     /* 松闸：先 100%（CCR > ARR 输出一直为高）；抱闸：立即 0 */
}

void brake_tick(float vbus)
{
    if (ms_since < 0x7FFFFFFFu) {
        ms_since++;
    }
    if (cmd_release && ms_since >= BRK_OVER_MS) {          /* 过励完了：保持平均 24 V */
        float d = vbus > BRK_V_COIL ? BRK_V_COIL / vbus : 1.0f;
        TIM4_CCR1 = (uint32_t)(d * (float)(BRK_ARR + 1u));
    }
}

int brake_released(void) { return cmd_release && ms_since >= BRK_RELEASE_MS; }
int brake_engaged(void) { return !cmd_release && ms_since >= BRK_ENGAGE_MS; }
int brake_cmd(void) { return (int)cmd_release; }

/* WQ-ENCIF 驱动。引脚（第 98 轮 B 版原理图）：PA4 片选（软件控制）、PA5 SCK、PA6 MISO、PA7 MOSI（AF5 = SPI1），PB1 芯片复位。 */
#include "encif.h"
#include "regs.h"

static void delay_cycles(volatile uint32_t n)
{
    while (n--) {
    }
}

void encif_init_bus(void)
{
    RCC_AHB2ENR |= RCC_GPIOAEN | RCC_GPIOBEN;
    RCC_APB2ENR |= RCC_SPI1EN;

    /* PA4 推挽输出（片选，先拉高）；PA5/6/7 复用 AF5（STM32G431 数据手册 DS12589 复用功能表：PA5/PA6/PA7 的 SPI1 为 AF5） */
    GPIO_BSRR(GPIOA_BASE) = 1u << 4;
    GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(0xFFu << 8)) | (1u << 8) | (2u << 10) | (2u << 12) | (2u << 14);
    GPIO_OSPEEDR(GPIOA_BASE) |= 0xFFu << 8;
    GPIO_AFRL(GPIOA_BASE) = (GPIO_AFRL(GPIOA_BASE) & ~(0xFFFu << 20)) | (5u << 20) | (5u << 24) | (5u << 28);
    /* PB1 推挽输出（芯片复位，低有效，先拉低） */
    GPIO_BSRR(GPIOB_BASE) = 1u << (16 + 1);
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(3u << 2)) | (1u << 2);

    /* SPI1：主机、模式 0（CPOL=0 CPHA=0）、170 MHz/64 = 2.66 MHz（芯片要求 SCLK ≤ 50 MHz/10）、软件片选、8 位 */
    SPI1_CR1 = SPI_CR1_MSTR | SPI_CR1_BR_DIV64 | SPI_CR1_SSM | SPI_CR1_SSI;
    SPI1_CR2 = SPI_CR2_DS_8BIT | SPI_CR2_FRXTH;
    SPI1_CR1 |= SPI_CR1_SPE;
}

void encif_reset(void)
{
    GPIO_BSRR(GPIOB_BASE) = 1u << (16 + 1);
    delay_cycles(1000);
    GPIO_BSRR(GPIOB_BASE) = 1u << 1;
    delay_cycles(1000);  /* 芯片同步器与上电对齐要几拍（50 MHz 下 < 1 µs） */
}

static uint8_t xfer(uint8_t b)
{
    while (!(SPI1_SR & SPI_SR_TXE)) {
    }
    SPI1_DR8 = b;
    while (!(SPI1_SR & SPI_SR_RXNE)) {
    }
    return SPI1_DR8;
}

static uint32_t frame(uint8_t cmd, uint32_t data)
{
    uint32_t r = 0;
    GPIO_BSRR(GPIOA_BASE) = 1u << (16 + 4);   /* 片选拉低 */
    xfer(cmd);
    for (int i = 3; i >= 0; i--) {
        r = (r << 8) | xfer((uint8_t)(data >> (8 * i)));
    }
    while (SPI1_SR & SPI_SR_BSY) {
    }
    GPIO_BSRR(GPIOA_BASE) = 1u << 4;          /* 片选拉高：一帧结束 */
    return r;
}

uint32_t encif_read(uint8_t addr) { return frame(addr & 0x7F, 0); }

void encif_write(uint8_t addr, uint32_t data) { (void)frame(0x80 | (addr & 0x7F), data); }

/* WQ-ENCIF 驱动：40 位一帧（8 位命令 + 32 位数据，高位先出），SPI 模式 0。寄存器见第 92 轮规格。 */
#ifndef ENCIF_H
#define ENCIF_H
#include <stdint.h>

#define ENCIF_ID 0x454E4331u      /* "ENC1" */
#define ENCIF_R_ID 0
#define ENCIF_R_CTRL 1            /* 位 0 使能、1 反向、2 Z 清零、4–7 滤波长度 */
#define ENCIF_R_STATUS 2          /* 位 0 方向、1 错误、2 Z 已锁存；写 1 清位 1、位 2 */
#define ENCIF_R_CNT 3
#define ENCIF_R_IDX 4
#define ENCIF_ST_ERR (1u << 1)
#define ENCIF_ST_IVLD (1u << 2)

void encif_init_bus(void);
void encif_reset(void);
uint32_t encif_read(uint8_t addr);
void encif_write(uint8_t addr, uint32_t data);

#endif

/* 启动代码：向量表、复制 .data、清零 .bss、进 main（第 102 轮：外设中断向量；复位后第一件事打开 FPU）。 */
#include <stdint.h>

extern uint32_t _estack, _sidata, _sdata, _edata, _sbss, _ebss;
int main(void);
void ADC1_2_IRQHandler(void);
void FDCAN1_IT0_IRQHandler(void);

void Reset_Handler(void)
{
    *(volatile uint32_t *)0xE000ED88u |= 0xFu << 20;   /* SCB_CPACR：先打开 FPU，之后的代码可能用浮点寄存器 */
    __asm volatile("dsb\n isb");
    uint32_t *s = &_sidata, *d = &_sdata;
    while (d < &_edata) {
        *d++ = *s++;
    }
    for (d = &_sbss; d < &_ebss;) {
        *d++ = 0;
    }
    main();
    for (;;) {
    }
}

void Default_Handler(void)
{
    for (;;) {
    }
}

/* 向量表：16 个内核异常 + 外设中断（STM32G431：ADC1_2 = 18、FDCAN1_IT0 = 21，其余不用） */
#define D Default_Handler
__attribute__((section(".isr_vector"), used)) const void *const vectors[16 + 26] = {
    &_estack, Reset_Handler, D, D, D, D, D, 0, 0, 0, 0, D, D, 0, D, D,   /* SP、复位、NMI、HardFault…SysTick */
    D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D,                /* 外设中断 0–17 */
    ADC1_2_IRQHandler, D, D, FDCAN1_IT0_IRQHandler, D, D, D, D,          /* 18–25 */
};

/* STM32G431CB：128 KB Flash，SRAM1 + SRAM2 共 22 KB（RM0440 存储器映射） */
MEMORY
{
  FLASH (rx) : ORIGIN = 0x08000000, LENGTH = 128K
  RAM (rwx) : ORIGIN = 0x20000000, LENGTH = 22K
}
_estack = ORIGIN(RAM) + LENGTH(RAM);
SECTIONS
{
  .text : { KEEP(*(.isr_vector)) *(.text*) *(.rodata*) . = ALIGN(4); } > FLASH
  _sidata = LOADADDR(.data);
  .data : { _sdata = .; *(.data*) . = ALIGN(4); _edata = .; } > RAM AT > FLASH
  .bss (NOLOAD) : { _sbss = .; *(.bss*) *(COMMON) . = ALIGN(4); _ebss = .; } > RAM
}

// STM32G431CB 仿真平台（Renode）——只描述本轮固件用到的部分。地址按 RM0440《STM32G4 参考手册》的存储器映射。
// 第 100 轮：驱动板 B 版固件仿真；第 102 轮加 TIM1、ADC1、FDCAN1（自写外设，见 WqDrive.cs）、PLL 170 MHz；第 107 轮 SPI3；第 110 轮 TIM4（抱闸）。
// 地址与中断号对照 ST 官方 CMSIS 头文件 stm32g431xx.h 核对。示例，非 ST 官方平台文件。
cpu: CPU.CortexM @ sysbus
    cpuType: "cortex-m4f"
    nvic: nvic

// NVIC 与 SysTick；固件把系统时钟从 HSI16 切到 PLL 170 MHz（RM0440 RCC 章）
nvic: IRQControllers.NVIC @ sysbus 0xE000E000
    systickFrequency: 170000000
    -> cpu@0

// 128 KB Flash（RM0440 存储器映射：0x0800 0000），SRAM1 16 KB + SRAM2 6 KB 连续（0x2000 0000，共 22 KB）
flash: Memory.MappedMemory @ sysbus 0x08000000
    size: 0x20000

sram: Memory.MappedMemory @ sysbus 0x20000000
    size: 0x5800

// GPIOA/GPIOB（AHB2，RM0440 存储器映射：0x4800 0000 / 0x4800 0400）
gpioPortA: GPIOPort.STM32_GPIOPort @ sysbus <0x48000000, +0x400>

gpioPortB: GPIOPort.STM32_GPIOPort @ sysbus <0x48000400, +0x400>

// SPI1（APB2，RM0440 存储器映射：0x4001 3000）
spi1: SPI.STM32SPI @ sysbus 0x40013000

// SPI3（APB1，0x4000 3C00）：读输出端绝对值编码器 SSI（第 107 轮；地址对照 ST 官方 CMSIS 头文件）
spi3: SPI.STM32SPI @ sysbus 0x40003C00

ssi: Miscellaneous.WqSsiEncoder @ spi3
    motor: tim1

// RCC（0x4002 1000）：只做固件等待的就绪位（HSIRDY、PLLRDY、SWS），见 WqDrive.cs 的 WqRcc
rcc: Miscellaneous.WqRcc @ sysbus 0x40021000

// FLASH 接口（0x4002 2000，等待周期）、PWR（0x4000 7000，主电压调节器提升模式）只占位
flashif: Memory.MappedMemory @ sysbus 0x40022000
    size: 0x400

pwr: Memory.MappedMemory @ sysbus 0x40007000
    size: 0x400

// TIM1（APB2 0x4001 2C00）+ 逆变桥 + 电机 + 减速器 + 负载
tim1: Miscellaneous.WqTim1Motor @ sysbus 0x40012C00
    IRQ -> nvic@25

// TIM4（APB1 0x4000 0800）：抱闸 PWM（第 110 轮；地址对照 ST 官方 CMSIS 头文件），抱闸模型挂在电机上
tim4: Miscellaneous.WqTim4Brake @ sysbus 0x40000800
    motor: tim1

// ADC1（AHB2 0x5000 0000）注入组，中断 ADC1_2 = 18
adc1: Miscellaneous.WqAdc1 @ sysbus 0x50000000
    motor: tim1
    IRQ -> nvic@18

// FDCAN1（APB1 0x4000 6400，中断 FDCAN1_IT0 = 21）与消息 RAM（SRAMCAN 0x4000 A400）
fdcan1: Miscellaneous.WqFdcan1 @ sysbus 0x40006400
    IRQ -> nvic@21

sramcan: Memory.MappedMemory @ sysbus 0x4000A400
    size: 0x400

// WQ-ENCIF 寄存器级模型 + 虚拟电机（Renode 外设，挂在 spi1 上）。第 100 轮：驱动板 B 版固件仿真。
// 规则同第 92 轮规格（factory/designs/wq-encif/rtl/wq_encif.v 文件头、model/encif.py）：
//   一帧 40 位 = 8 位命令（位 7：1 写 0 读；低 7 位地址）+ 32 位数据，高位先出；读在命令字节收完时取快照；写在第 40 位生效。
//   寄存器 0 ID "ENC1"；1 CTRL（位 0 使能、1 反向、2 Z 清零、4–7 滤波）；2 STATUS（位 0 方向、1 错误、2 Z 已锁存、3–5 A/B/Z 电平；
//   写 1 清位 1、位 2）；3 CNT（可写）；4 IDX（Z 上升沿时的计数）。
// 芯片 RTL 已在第 92/93 轮与 Python 模型逐拍比对；这里只做寄存器级，跑得快。示例，芯片未流片。
//
// 虚拟电机：转速曲线（时刻 s : 转速 rpm，分段线性）积分成位置（计数，2500 线 ×4 = 10000 计数/转）；
// Z 在绝对位置为 10000 的整数倍处；芯片计数 = 复位释放后走过的计数。
// 第 102 轮：UseMotor "tim1" 后位置改从电机仿真外设（WqDrive.cs 的 WqTim1Motor）取，转速曲线不再用。
using System;
using System.Collections.Generic;
using System.Globalization;
using Antmicro.Renode.Core;
using Antmicro.Renode.Logging;
using Antmicro.Renode.Peripherals;
using Antmicro.Renode.Peripherals.SPI;

namespace Antmicro.Renode.Peripherals.SPI
{
    public class WqEncif : ISPIPeripheral, IGPIOReceiver
    {
        public const int CPR = 10000;
        public const uint ID = 0x454E4331;

        public WqEncif(IMachine machine)
        {
            this.machine = machine;
            prof = new List<double[]> { new double[] { 0, 0 } };
            Reset();
        }

        // ---------------------------------------------------------------- 监视器命令（仿真脚本用）
        // 转速曲线，如 "0:0,0.1:600,0.5:600"
        public void Profile(string spec)
        {
            var l = new List<double[]>();
            foreach(var seg in spec.Split(','))
            {
                var kv = seg.Split(':');
                l.Add(new double[] { double.Parse(kv[0], CultureInfo.InvariantCulture), double.Parse(kv[1], CultureInfo.InvariantCulture) });
            }
            prof = l;
        }

        public void UseMotor(string name)
        {
            IPeripheral p;
            if(!machine.TryGetByName("sysbus." + name, out p)) throw new ArgumentException("找不到 " + name);
            motor = p;
            motorPos = p.GetType().GetMethod("EncoderCounts");
            plast = Floor(PosAt(Now()));
            relBase = plast;
        }

        public void StartPos(int counts) { pos0 = counts; plast = Floor(PosAt(Now())); }
        public void InjectError() { Update(); err = 1; errInjected++; }
        public void Absent(bool v) { absent = v; }
        public string Truth()
        {
            var t = Now();
            var p = PosAt(t);
            return string.Format(CultureInfo.InvariantCulture, "T {0:F6} {1:F3} {2:F3} {3} {4}", t, p - pos0, RpmAt(t), Floor(p), relBase);
        }

        // ---------------------------------------------------------------- SPI
        public byte Transmit(byte b)
        {
            if(absent || !selected || !rstn)
            {
                return 0;
            }
            byte ret = 0;
            if(nbyte == 0)
            {
                cmd = b;
                if((cmd & 0x80) == 0)
                {
                    Update();
                    snap = Reg(cmd & 0x7F);
                }
            }
            else if(nbyte <= 4)
            {
                if((cmd & 0x80) == 0)
                {
                    ret = (byte)(snap >> (8 * (4 - nbyte)));
                }
                else
                {
                    wdata = (wdata << 8) | b;
                    if(nbyte == 4)
                    {
                        Update();
                        Write(cmd & 0x7F, wdata);
                    }
                }
            }
            nbyte++;
            frames += nbyte == 5 ? 1 : 0;
            return ret;
        }

        public void FinishTransmission() { }

        // GPIO 0：片选（低有效，PA4）；GPIO 1：复位（低有效，PB1）
        public void OnGPIO(int number, bool value)
        {
            if(number == 0)
            {
                selected = !value;
                nbyte = 0;
                wdata = 0;
            }
            else if(number == 1)
            {
                if(!value)
                {
                    ResetRegs();
                }
                else if(!rstn)
                {
                    plast = Floor(PosAt(Now()));
                    relBase = plast;
                }
                rstn = value;
            }
        }

        public void Reset()
        {
            ResetRegs();
            selected = false;
            rstn = true;
            nbyte = 0;
            plast = Floor(PosAt(Now()));
            relBase = plast;
        }

        public int Frames => frames;

        // ---------------------------------------------------------------- 寄存器
        private void ResetRegs()
        {
            en = 1; inv = 0; zclr = 0; flen = 3;
            dir = 1; err = 0; ivld = 0;
            cnt = 0; idx = 0;
        }

        private uint Reg(int a)
        {
            switch(a)
            {
            case 0: return ID;
            case 1: return (uint)(en | inv << 1 | zclr << 2 | flen << 4);
            case 2:
                var ph = ((plast % 4) + 4) % 4;               // 正交相位 0..3：A 领先 B
                int ra = (ph == 1 || ph == 2) ? 1 : 0, rb = (ph == 2 || ph == 3) ? 1 : 0;
                int rz = (((plast % CPR) + CPR) % CPR) == 0 ? 1 : 0;
                return (uint)(dir | err << 1 | ivld << 2 | ra << 3 | rb << 4 | rz << 5);
            case 3: return cnt;
            case 4: return idx;
            default: return 0;
            }
        }

        private void Write(int a, uint v)
        {
            if(a == 1) { en = (int)(v & 1); inv = (int)(v >> 1 & 1); zclr = (int)(v >> 2 & 1); flen = (int)(v >> 4 & 0xF); }
            else if(a == 2) { if((v & 2) != 0) err = 0; if((v & 4) != 0) ivld = 0; }
            else if(a == 3) { cnt = v; }
        }

        // 把虚拟电机推进到当前时刻：逐个处理途中的 Z
        private void Update()
        {
            if(!rstn)
            {
                return;
            }
            long p = Floor(PosAt(Now()));
            while(p != plast)
            {
                int s = p > plast ? 1 : -1;
                // 下一个 Z（10000 的整数倍）：正转取 (plast, p]，反转取 [p, plast)
                long z = s > 0 ? FloorDiv(plast, CPR) * CPR + CPR : FloorDiv(plast - 1, CPR) * CPR;
                bool hit = s > 0 ? z <= p : z >= p;
                long to = hit ? z : p;
                Step(to - plast, s);
                plast = to;
                if(hit)
                {
                    idx = cnt; ivld = 1;
                    if(zclr == 1 && en == 1)
                    {
                        cnt = 0;
                    }
                }
            }
        }

        private void Step(long d, int s)
        {
            if(d == 0 || en == 0)
            {
                return;
            }
            cnt = (uint)(cnt + (inv == 1 ? -d : d));
            dir = (s > 0) ^ (inv == 1) ? 1 : 0;
        }

        // ---------------------------------------------------------------- 虚拟电机
        private double Now() { return machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds; }

        private double RpmAt(double t)
        {
            if(t <= prof[0][0]) return prof[0][1];
            for(int i = 1; i < prof.Count; i++)
            {
                if(t <= prof[i][0])
                {
                    var a = prof[i - 1]; var b = prof[i];
                    return a[1] + (b[1] - a[1]) * (t - a[0]) / (b[0] - a[0]);
                }
            }
            return prof[prof.Count - 1][1];
        }

        // 绝对位置（计数）= 起始位置 + ∫ rpm/60·CPR dt（分段线性，梯形精确积分）；接了电机则取电机轴位置
        private double PosAt(double t)
        {
            if(motor != null)
            {
                return pos0 + (double)motorPos.Invoke(motor, new object[] { t });
            }
            double acc = 0, k = CPR / 60.0;
            double t0 = 0, r0 = RpmAt(0);
            var pts = new List<double>();
            foreach(var q in prof) if(q[0] > 0 && q[0] < t) pts.Add(q[0]);
            pts.Add(t);
            foreach(var t1 in pts)
            {
                var r1 = RpmAt(t1);
                acc += (r0 + r1) / 2 * (t1 - t0) * k;
                t0 = t1; r0 = r1;
            }
            return pos0 + acc;
        }

        private static long Floor(double x) { return (long)Math.Floor(x + 1e-9); }
        private static long FloorDiv(long a, long b) { return (long)Math.Floor((double)a / b); }

        private readonly IMachine machine;
        private IPeripheral motor;
        private System.Reflection.MethodInfo motorPos;
        private List<double[]> prof;
        private double pos0;
        private long plast, relBase;
        private bool selected, rstn, absent;
        private int nbyte, frames, errInjected;
        private byte cmd;
        private uint snap, wdata, cnt, idx;
        private int en, inv, zclr, flen, dir, err, ivld;
    }
}

// 关节驱动板 B 版的“功率级 + 被控对象”仿真外设（Renode，运行时编译）。第 102 轮。
//   WqTim1Motor：TIM1 子集（三相中心对齐 PWM）+ 逆变桥平均模型 + 三相永磁同步电机 d/q 模型 + 减速器 + 摆臂负载
//   WqAdc1    ：ADC1 注入组子集（TIM1 更新时刻采三相电流和母线电压，INA240 40 mV/A、零点 1.65 V；分压 6.8/108.8）
//   WqSsiEncoder：输出端绝对值编码器（SSI，挂在 SPI3；第 107 轮）：17 位单圈，从电机模型取输出轴角度（含注入的“减速器打滑”）
//   WqTim4Brake：TIM4 子集（CH1 PWM，第 110 轮）+ 抱闸线圈：占空比 × 母线 = 线圈平均电压，电流一阶滞后；吸合 / 释放带回差；抱住时给电机轴摩擦力矩
//   WqFdcan1  ：FDCAN1 子集（经典 CAN；消息 RAM 按 G4 布局：Rx FIFO0 0xB0 起、Tx 缓冲 0x278 起，每个元素 18 字）+ 仿真 CAN 主站
// 寄存器地址、偏移、位、中断号对照 ST 官方 CMSIS 头文件 stm32g431xx.h 与 HAL stm32g4xx_hal_fdcan.c 核对（见 test_drv_b_motor.py）。
// 电机参数：力矩常数 0.15 N·m/A、额定 1.27 N·m 取第 88 轮示例电机；减速比 100 取零件库 Harmonic Drive CSF-17-100；
// 其余（电阻、电感、极对数、惯量、摩擦、摆臂）是示例值。示例，不是某个型号。
using System;
using System.Collections.Generic;
using System.Globalization;
using Antmicro.Renode.Core;
using Antmicro.Renode.Logging;
using Antmicro.Renode.Peripherals.Bus;
using Antmicro.Renode.Peripherals.Timers;
using Antmicro.Renode.Time;

namespace Antmicro.Renode.Peripherals.Miscellaneous
{
    public class WqTim1Motor : IDoubleWordPeripheral, IKnownSize
    {
        // ---------------------------------------------------------------- 参数
        public const double Vbus0 = 48.0;            // 母线（第 88 轮）
        public const double Kt = 0.15;               // N·m/A（第 88 轮示例电机）
        public const int P = 5;                      // 极对数（示例）
        public const double Psi = Kt / (1.5 * P);    // 永磁磁链 Wb：Kt = 1.5·p·ψ（幅值不变变换）
        public const double Rs = 0.12;               // 相电阻 Ω（示例）
        public const double Ls = 0.0002;             // 相电感 H（示例，Ld = Lq）
        public const double Jm = 4.86e-5;            // 转子惯量 kg·m²（示例：取零件库同功率等级 SGM7J-04A 的值）
        public const double N = 100.0;               // 减速比（零件库 CSF-17-100）
        public const double Bv = 1e-5;               // 粘滞摩擦 N·m·s/rad（电机侧，示例）
        public const double Tc = 0.01;               // 库仑摩擦 N·m（电机侧，示例）
        public const double Mass = 1.0, Arm = 0.3;   // 摆臂：1 kg 集中质量在 0.3 m（示例）
        public const double Dead = 200e-9;           // 死区 s（第 88 轮：约 200 ns）
        public const double G = 9.80665;
        public const double Rshort = 0.02, Lshort = 2e-6;   // 注入的 A–B 相间短路（示例）
        // 第 110 轮：抱闸（失电制动，装在电机轴上；示例）——线圈 24 V、0.42 A，时间常数 25 ms；吸合 ≥ 70%、释放 ≤ 30% 额定电流；
        // 抱住时静摩擦 2.0 N·m、打滑后动摩擦 1.6 N·m（电机侧）
        public const double BrkV = 24.0, BrkI = 0.42, BrkTau = 0.025, BrkTs = 2.0, BrkTk = 1.6;
        public const double BrkR = BrkV / BrkI, BrkL = BrkTau * BrkR;

        public WqTim1Motor(IMachine machine)
        {
            this.machine = machine;
            pwm = new LimitTimer(machine.ClockSource, 170000000, this, "pwm", 4250, Direction.Ascending, false, WorkMode.Periodic, true);
            pwm.LimitReached += OnUpdate;
            Reset();
        }

        public long Size => 0x400;
        public GPIO IRQ { get; } = new GPIO();      // TIM1_UP（中断 25），本固件不用
        public WqAdc1 Adc { get; set; }
        public WqTim4Brake Brake { get; set; }      // 第 110 轮：没挂抱闸时当一直松开

        // ---------------------------------------------------------------- 监视器命令
        public void LockRotor(bool v) { Advance(); locked = v; if(v) w = 0; }
        public void ExtraMass(double kg) { Advance(); extra = kg; }
        public void SetVbus(double v) { Advance(); vbus = v; }
        public void ShortAB(bool v) { Advance(); shortOn = v; if(!v) isc = 0; }
        public void StartJoint(double deg) { th = deg / 180 * Math.PI * N; }
        // 第 107 轮：减速器打滑——输出轴相对电机轴突然错开 deg 度（输出端编码器看得到，电机侧编码器看不到）
        public void Slip(double deg) { Advance(); slip += deg / 180 * Math.PI; }
        // 第 110 轮：抱闸线圈断线（线圈电流恒为 0 → 一直抱着）
        public void BrakeBroken(bool v) { Advance(); brkBroken = v; }

        // 输出轴角度（rad，含打滑）：给输出端绝对值编码器
        public double OutputAngle(double t)
        {
            return (th + w * Math.Max(0, t - tLast)) / N + slip;
        }
        public string Truth()
        {
            Advance();
            var ia = Ia(); var ib = Ib();
            // 时刻 s、id A、iq A、电机转速 rpm、关节角 °、ia、ib、MOE、母线 V、电机轴计数、最近一次关管时刻、电角度 °、∫iq dt（A·s）、
            // 抱闸线圈电流 A、抱闸松开（1）/ 抱住（0）（第 110 轮）
            return string.Format(CultureInfo.InvariantCulture, "M {0:F6} {1:F5} {2:F5} {3:F4} {4:F6} {5:F4} {6:F4} {7} {8:F4} {9:F2} {10:F7} {11:F3} {12:F9} {13:F4} {14}",
                Now(), id, iq, w * 60 / (2 * Math.PI), (th / N + slip) * 180 / Math.PI, ia, ib, moe ? 1 : 0, vbus,
                th / (2 * Math.PI) * 10000.0, offTime, ((P * th) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) * 180 / Math.PI, iqInt,
                brkI, brkOpen ? 1 : 0);
        }

        // 编码器（WQ-ENCIF 经反射取）：电机轴走过的计数，2500 线 ×4
        public double EncoderCounts(double t)
        {
            return (th + w * Math.Max(0, t - tLast)) / (2 * Math.PI) * 10000.0;
        }

        // ---------------------------------------------------------------- 寄存器（偏移按 TIM_TypeDef）
        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x00: return cr1;
            case 0x04: return cr2;
            case 0x0C: return dier;
            case 0x10: return sr;
            case 0x18: return ccmr1;
            case 0x1C: return ccmr2;
            case 0x20: return ccer;
            case 0x28: return psc;
            case 0x2C: return arr;
            case 0x30: return rcr;
            case 0x34: return ccrP[0];
            case 0x38: return ccrP[1];
            case 0x3C: return ccrP[2];
            case 0x44: return bdtr;
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            switch(off)
            {
            case 0x00: cr1 = v; Apply(); break;
            case 0x04: cr2 = v; break;
            case 0x0C: dier = v; break;
            case 0x10: sr &= v; break;                       // 写 0 清
            case 0x14: if((v & 1) != 0) { LoadShadow(); } break;   // EGR.UG
            case 0x18: ccmr1 = v; break;
            case 0x1C: ccmr2 = v; break;
            case 0x20: ccer = v; break;
            case 0x28: psc = v & 0xFFFF; Apply(); break;
            case 0x2C: arr = v & 0xFFFF; Apply(); break;
            case 0x30: rcr = v & 0xFFFF; Apply(); break;
            case 0x34: ccrP[0] = v & 0xFFFF; break;
            case 0x38: ccrP[1] = v & 0xFFFF; break;
            case 0x3C: ccrP[2] = v & 0xFFFF; break;
            case 0x44:
                Advance();
                bdtr = v;
                moe = (v & (1u << 15)) != 0;                   // BDTR.MOE
                if(!moe) { offTime = Now(); }
                break;
            }
        }

        public void Reset()
        {
            cr1 = cr2 = dier = sr = ccmr1 = ccmr2 = ccer = psc = rcr = bdtr = 0;
            arr = 0xFFFF;
            ccrP = new uint[3]; ccrA = new uint[3];
            moe = false; locked = false; shortOn = false;
            id = iq = w = th = isc = iqInt = slip = 0; extra = 0; vbus = Vbus0;
            brkI = 0; brkOpen = false; brkBroken = false;      // 上电：线圈没电，抱着
            tLast = 0; offTime = -1;
            pwm.Enabled = false;
        }

        public double MoeOffTime => offTime;
        public void Sync() { Advance(); }           // 第 110 轮：抱闸占空比变化前先把物理积分到现在

        // ---------------------------------------------------------------- PWM 与更新事件
        // 中心对齐、RCR = 1：每个 PWM 周期一次更新事件，周期 = ARR·(PSC+1)·(RCR+1) / 170 MHz
        private void Apply()
        {
            bool cen = (cr1 & 1) != 0;
            ulong lim = (ulong)arr * (psc + 1) * (rcr + 1);
            if(lim == 0) lim = 1;
            pwm.Limit = lim;
            if(cen && !pwm.Enabled) { tLast = Now(); }
            pwm.Enabled = cen;
        }

        private void LoadShadow() { for(int k = 0; k < 3; k++) ccrA[k] = ccrP[k]; }

        private void OnUpdate()
        {
            Advance();                // 用这一周期生效的占空比积分到现在
            LoadShadow();             // 预装载：新的比较值从下个周期起生效
            sr |= 1;
            if(Adc != null) Adc.Convert(Ia(), Ib(), Ic(), vbus);
        }

        // ---------------------------------------------------------------- 物理
        private double Now() { return machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds; }

        private void Advance()
        {
            double t = Now();
            double dt = t - tLast;
            if(dt <= 0) return;
            int n = Math.Max(1, (int)Math.Ceiling(dt / 2e-6));
            double h = dt / n;
            for(int k = 0; k < n; k++) Step(h);
            tLast = t;
        }

        private double Duty(int k) { return arr == 0 ? 0 : Math.Min(1.0, (double)ccrA[k] / arr); }

        private void Step(double h)
        {
            double te = P * th;
            double c = Math.Cos(te), s = Math.Sin(te);
            double vd = 0, vq = 0, vab = 0;
            if(moe)
            {
                double da = Duty(0), db = Duty(1), dc = Duty(2), m = (da + db + dc) / 3;
                double[] cur = { Ia(), Ib(), Ic() };
                double dv = vbus * Dead * 20000.0;                 // 死区折算的电压误差（随电流方向）
                double va = vbus * (da - m) - dv * Math.Sign(cur[0]) + dv * (Math.Sign(cur[0]) + Math.Sign(cur[1]) + Math.Sign(cur[2])) / 3;
                double vb = vbus * (db - m) - dv * Math.Sign(cur[1]) + dv * (Math.Sign(cur[0]) + Math.Sign(cur[1]) + Math.Sign(cur[2])) / 3;
                double vc = -va - vb;
                double al = va, be = (vb - vc) / Math.Sqrt(3);
                vd = al * c + be * s;
                vq = -al * s + be * c;
                vab = vbus * (da - db);
            }
            else
            {
                // 关管：续流二极管把电流迅速回馈到母线，按反压 −Vbus·sign(i) 近似
                vd = -vbus * Math.Sign(id) * 0.5;
                vq = -vbus * Math.Sign(iq) * 0.5;
            }
            double we = P * w;
            double did = (vd - Rs * id + we * Ls * iq) / Ls;
            double diq = (vq - Rs * iq - we * Ls * id - we * Psi) / Ls;
            double nid = id + did * h, niq = iq + diq * h;
            if(!moe) { if(Math.Sign(nid) != Math.Sign(id)) nid = 0; if(Math.Sign(niq) != Math.Sign(iq)) niq = 0; }
            id = nid; iq = niq;
            iqInt += iq * h;
            // 相间短路电流（A→B），关管后按自身时间常数衰减
            if(shortOn || isc != 0)
            {
                double dis = ((shortOn && moe ? vab : 0) - Rshort * isc) / Lshort;
                isc += dis * h;
                if(!shortOn && Math.Abs(isc) < 1e-3) isc = 0;
            }
            // 机械：J·dω/dt = Te − 负载（重力经减速器折算 + 摩擦）
            double teM = 1.5 * P * Psi * iq;
            double thJ = th / N + slip;
            double tg = (Mass + extra) * G * Arm * Math.Sin(thJ) / N;
            double jl = Jm + (Mass + extra) * Arm * Arm / (N * N);
            double tf = Bv * w + Tc * Math.Tanh(w / 0.5);
            // 第 110 轮：抱闸线圈（平均模型：PWM 占空比 × 母线 = 线圈平均电压；撤电后经续流二极管按时间常数衰减）
            double dutyB = Brake == null ? -1 : Brake.Duty();
            if(dutyB < 0) { brkOpen = true; }
            else
            {
                brkI += (dutyB * vbus - BrkR * brkI) / BrkL * h;
                if(brkI < 0 || brkBroken) brkI = 0;
                if(!brkOpen && brkI >= 0.7 * BrkI) brkOpen = true;
                else if(brkOpen && brkI <= 0.3 * BrkI) brkOpen = false;
            }
            if(locked) { w = 0; return; }
            double tnet = teM - tg - tf;
            if(!brkOpen)
            {
                if(Math.Abs(w) < 1e-6 && Math.Abs(tnet) <= BrkTs) { w = 0; return; }   // 静摩擦：抱住不动
                double w2 = w + (tnet - BrkTk * Math.Sign(w)) / jl * h;            // 打滑：动摩擦减速
                if(w != 0 && Math.Sign(w2) != Math.Sign(w)) { w = 0; return; }
                w = w2;
                th += w * h;
                return;
            }
            w += tnet / jl * h;
            th += w * h;
        }

        private double Ia() { var te = P * th; return id * Math.Cos(te) - iq * Math.Sin(te) + isc; }
        private double Ib() { var te = P * th - 2 * Math.PI / 3; return id * Math.Cos(te) - iq * Math.Sin(te) - isc; }
        private double Ic() { var te = P * th + 2 * Math.PI / 3; return id * Math.Cos(te) - iq * Math.Sin(te); }

        private readonly IMachine machine;
        private readonly LimitTimer pwm;
        private uint cr1, cr2, dier, sr, ccmr1, ccmr2, ccer, psc, arr, rcr, bdtr;
        private uint[] ccrP, ccrA;
        private bool moe, locked, shortOn;
        private double id, iq, w, th, isc, extra, vbus, tLast, offTime, iqInt, slip, brkI;
        private bool brkOpen, brkBroken;
    }

    // ==================================================================== TIM4（抱闸 PWM，第 110 轮）
    // 只做 CH1 PWM 模式 1 向上计数：占空比 = CCR1 / (ARR + 1)（CCR1 > ARR 时恒高）；CEN、CC1E、OC1M 不对时输出低（线圈没电）。
    // 偏移、位对照 ST 官方 CMSIS 头文件（TIM_TypeDef；OC1M 位 6:4 + 位 16，CC1E 位 0，CEN 位 0）。20 kHz 的开关纹波不模拟（线圈时间常数 25 ms）。
    public class WqTim4Brake : IDoubleWordPeripheral, IKnownSize
    {
        public WqTim4Brake(IMachine machine, WqTim1Motor motor)
        {
            this.motor = motor;
            motor.Brake = this;
            Reset();
        }

        public long Size => 0x400;

        public double Duty()
        {
            uint oc1m = ((ccmr1 >> 4) & 7) | (((ccmr1 >> 16) & 1) << 3);
            if((cr1 & 1) == 0 || (ccer & 1) == 0 || oc1m != 6) return 0;
            return Math.Min(1.0, (double)ccr1 / (arr + 1.0));
        }

        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x00: return cr1;
            case 0x18: return ccmr1;
            case 0x20: return ccer;
            case 0x28: return psc;
            case 0x2C: return arr;
            case 0x34: return ccr1;
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            motor.Sync();
            switch(off)
            {
            case 0x00: cr1 = v; break;
            case 0x18: ccmr1 = v; break;
            case 0x20: ccer = v; break;
            case 0x28: psc = v & 0xFFFF; break;
            case 0x2C: arr = v & 0xFFFF; break;
            case 0x34: ccr1 = v & 0xFFFF; break;
            }
        }

        public void Reset() { cr1 = ccmr1 = ccer = psc = ccr1 = 0; arr = 0xFFFF; }

        private readonly WqTim1Motor motor;
        private uint cr1, ccmr1, ccer, psc, arr, ccr1;
    }

    // ==================================================================== ADC1 注入组
    public class WqAdc1 : IDoubleWordPeripheral, IKnownSize
    {
        public WqAdc1(IMachine machine, WqTim1Motor motor)
        {
            this.motor = motor;
            motor.Adc = this;
            Reset();
        }

        public long Size => 0x400;
        public GPIO IRQ { get; } = new GPIO();      // ADC1_2（中断 18）

        public void Convert(double ia, double ib, double ic, double vbus)
        {
            if((cr & 1) == 0 || (cr & (1u << 3)) == 0 || ((jsqr >> 7) & 3) == 0) return;   // ADEN、JADSTART、JEXTEN
            jdr[0] = Code(1.65 + 0.04 * ia);
            jdr[1] = Code(1.65 + 0.04 * ib);
            jdr[2] = Code(1.65 + 0.04 * ic);
            jdr[3] = Code(vbus * 6.8 / 108.8);
            isr |= (1u << 5) | (1u << 6);                  // JEOC、JEOS
            Update();
        }

        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x00: return isr;
            case 0x04: return ier;
            case 0x08: return cr;
            case 0x4C: return jsqr;
            case 0x80: return jdr[0];
            case 0x84: return jdr[1];
            case 0x88: return jdr[2];
            case 0x8C: return jdr[3];
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            switch(off)
            {
            case 0x00: isr &= ~v; Update(); break;          // 写 1 清
            case 0x04: ier = v; Update(); break;
            case 0x08:
                cr = v & ~(1u << 31);                        // ADCAL 立即完成
                if((v & 1) != 0) isr |= 1;                   // ADRDY
                break;
            case 0x4C: jsqr = v; break;
            }
        }

        public void Reset() { isr = ier = cr = jsqr = 0; jdr = new uint[4]; IRQ.Unset(); }

        private void Update() { IRQ.Set((isr & ier & (1u << 6)) != 0); }   // JEOS 中断
        private static uint Code(double v) { return (uint)Math.Max(0, Math.Min(4095, Math.Round(v / 3.3 * 4095))); }

        private readonly WqTim1Motor motor;
        private uint isr, ier, cr, jsqr;
        private uint[] jdr;
    }

    // ==================================================================== 输出端绝对值编码器（SSI，第 107 轮）
    // 帧（示例格式）：24 个时钟，第 1 位起始位恒 1，接着 17 位单圈位置（二进制、高位先出，131 072 计数/圈），再 1 位错误位（0 正常），其余补 0。
    // 两帧之间时钟停 ≥ 15 µs（SSI 的单稳态时间）编码器重新锁存位置；“线断”时 RS-485 接收端读回全 1。
    public class WqSsiEncoder : Antmicro.Renode.Peripherals.SPI.ISPIPeripheral
    {
        public const int BITS = 17;

        public WqSsiEncoder(IMachine machine, WqTim1Motor motor)
        {
            this.machine = machine;
            this.motor = motor;
            Reset();
        }

        public void Broken(bool v) { broken = v; }

        public byte Transmit(byte b)
        {
            double t = machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds;
            if(t - last > 15e-6 || nbyte >= 3)
            {
                double a = motor.OutputAngle(t) % (2 * Math.PI);
                if(a < 0) a += 2 * Math.PI;
                uint pos = (uint)Math.Floor(a / (2 * Math.PI) * (1 << BITS)) & ((1u << BITS) - 1);
                frame = (1u << 23) | (pos << 6);          // 起始位、17 位位置、错误位 0
                nbyte = 0;
            }
            last = t;
            byte r = broken ? (byte)0xFF : (byte)(frame >> (8 * (2 - nbyte)));
            nbyte++;
            return r;
        }

        public void FinishTransmission() { }
        public void Reset() { nbyte = 3; last = -1; frame = 0; }

        private readonly IMachine machine;
        private readonly WqTim1Motor motor;
        private bool broken;
        private int nbyte;
        private double last;
        private uint frame;
    }

    // ==================================================================== FDCAN1 + 仿真主站
    public class WqFdcan1 : IDoubleWordPeripheral, IKnownSize
    {
        public const ulong Ram = 0x4000A400;         // SRAMCAN_BASE
        public const uint RF0SA = 0xB0, TBSA = 0x278, ESIZE = 72;

        public WqFdcan1(IMachine machine)
        {
            this.machine = machine;
            Reset();
        }

        public long Size => 0x400;
        public GPIO IRQ { get; } = new GPIO();      // FDCAN1_IT0（中断 21）

        // 主站发一帧（标准 ID，数据十六进制）
        public void HostSend(int id, string hex)
        {
            var data = new List<byte>();
            for(int i = 0; i + 1 < hex.Length; i += 2) data.Add(byte.Parse(hex.Substring(i, 2), NumberStyles.HexNumber));
            log.Add(Line("rx", id, data.ToArray()));
            if((cccr & 1) != 0) return;                  // 还在初始化，收不到
            int fill = (int)(rxf0s & 0xF);
            if(fill >= 3) { return; }                    // FIFO 满，丢
            ulong a = Ram + RF0SA + (ulong)(putIdx * ESIZE);
            Bus.WriteDoubleWord(a, (uint)(id & 0x7FF) << 18);
            Bus.WriteDoubleWord(a + 4, (uint)data.Count << 16);
            for(int k = 0; k < 16; k++)
            {
                uint wv = 0;
                for(int b = 0; b < 4; b++) { int j = k * 4 + b; if(j < data.Count) wv |= (uint)data[j] << (8 * b); }
                if(k < 2) Bus.WriteDoubleWord(a + 8 + (ulong)(4 * k), wv);
            }
            putIdx = (putIdx + 1) % 3;
            fill++;
            rxf0s = (uint)fill | ((uint)getIdx << 8) | ((uint)putIdx << 16);
            ir |= 1;                                     // RF0N
            Update();
        }

        // 取出记录（每行：时刻 方向 ID 数据）；取后清空
        public string HostLog()
        {
            var s = string.Join("\n", log);
            log.Clear();
            return "CAN<<\n" + s + "\nCAN>>";
        }

        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x018: return cccr;
            case 0x01C: return nbtp;
            case 0x050: return ir;
            case 0x054: return ie;
            case 0x058: return ils;
            case 0x05C: return ile;
            case 0x080: return rxgfc;
            case 0x090: return rxf0s;
            case 0x0C4: return (uint)3 | ((uint)tPut << 16);   // TXFQS：总有空位，放入索引轮转
            case 0x0C8: return 0;                              // TXBRP：立即发完
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            switch(off)
            {
            case 0x018: cccr = v; break;
            case 0x01C: nbtp = v; break;
            case 0x050: ir &= ~v; Update(); break;
            case 0x054: ie = v; Update(); break;
            case 0x058: ils = v; break;
            case 0x05C: ile = v; Update(); break;
            case 0x080: rxgfc = v; break;
            case 0x094:                                        // RXF0A：确认读完
                {
                    int fill = (int)(rxf0s & 0xF);
                    if(fill > 0) { fill--; getIdx = ((int)v + 1) % 3; }
                    rxf0s = (uint)fill | ((uint)getIdx << 8) | ((uint)putIdx << 16);
                    break;
                }
            case 0x0CC:                                        // TXBAR：发送请求
                for(int k = 0; k < 3; k++)
                {
                    if((v & (1u << k)) == 0) continue;
                    ulong a = Ram + TBSA + (ulong)(k * ESIZE);
                    uint t0 = Bus.ReadDoubleWord(a), t1 = Bus.ReadDoubleWord(a + 4);
                    int dlc = (int)((t1 >> 16) & 0xF);
                    var d = new byte[Math.Min(8, dlc)];
                    for(int j = 0; j < d.Length; j++) d[j] = (byte)(Bus.ReadDoubleWord(a + 8 + (ulong)(j / 4 * 4)) >> (8 * (j % 4)));
                    if((cccr & 1) == 0) log.Add(Line("tx", (int)((t0 >> 18) & 0x7FF), d));
                    tPut = (k + 1) % 3;
                }
                break;
            }
        }

        public void Reset()
        {
            cccr = 1; nbtp = ir = ie = ils = ile = rxgfc = rxf0s = 0;
            putIdx = getIdx = tPut = 0;
            log = new List<string>();
            IRQ.Unset();
        }

        private IBusController Bus => machine.SystemBus;
        private void Update() { IRQ.Set((ir & ie & 1) != 0 && (ile & 1) != 0); }
        private string Line(string dir, int id, byte[] d)
        {
            return string.Format(CultureInfo.InvariantCulture, "F {0:F6} {1} {2:X3} {3}",
                machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds, dir, id, BitConverter.ToString(d).Replace("-", ""));
        }

        private readonly IMachine machine;
        private uint cccr, nbtp, ir, ie, ils, ile, rxgfc, rxf0s;
        private int putIdx, getIdx, tPut;
        private List<string> log;
    }

    // ==================================================================== RCC（只做固件等待的几个就绪位）
    public class WqRcc : IDoubleWordPeripheral, IKnownSize
    {
        public WqRcc() { Reset(); }
        public long Size => 0x400;

        public uint ReadDoubleWord(long off)
        {
            uint v;
            mem.TryGetValue(off, out v);
            if(off == 0x00)
            {
                if((v & (1u << 8)) != 0) v |= 1u << 10;       // HSION → HSIRDY
                if((v & (1u << 24)) != 0) v |= 1u << 25;      // PLLON → PLLRDY
            }
            if(off == 0x08) v = (v & ~0xCu) | ((v & 3) << 2);  // SWS 跟随 SW
            return v;
        }

        public void WriteDoubleWord(long off, uint v) { mem[off] = v; }
        public void Reset() { mem = new Dictionary<long, uint> { { 0x00, 1u << 8 }, { 0x08, 1 } }; }   // 上电：HSI16 开、系统时钟 HSI16

        private Dictionary<long, uint> mem;
    }
}
